contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call addToBalance by sending `amount` wei to c, then attempt withdrawBalance.
    // Parameters:
    // - amount: amount of wei to add to balance (must be provided by caller and test contract must hold it)
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "Insufficient test contract balance");
        // record c's balance before deposit
        uint beforeC = address(c).balance;
        // make deposit: this is a state-changing call that transfers Ether into c and updates userBalance for msg.sender (this contract)
        c.addToBalance{value: amount}();
        // after deposit, recorded user balance for this contract should be at least increased by amount
        uint recordedAfterDeposit = c.getBalance(address(this));
        // Now attempt withdraw; capture whether it reverted
        bool withdrew;
        uint beforeC2 = address(c).balance;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint recordedAfterWithdraw = c.getBalance(address(this));
        uint afterC = address(c).balance;

        // General rule:
        // If withdraw succeeded then (1) recorded balance for this contract is zero and (2) c's balance decreased by at least the amount that had been recorded just before withdraw (i.e., recordedAfterDeposit).
        // If withdraw reverted then recorded balance must remain unchanged and c's balance unchanged.
        assert(
            (withdrew && recordedAfterWithdraw == 0 && beforeC2 - afterC >= recordedAfterDeposit) ||
            (!withdrew && recordedAfterWithdraw == recordedAfterDeposit && beforeC2 == afterC)
        );
    }

    // receive to accept Ether when withdraw sends funds back
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send amount to c via addToBalance and check balances updated accordingly
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read balances before
        uint256 beforeUserBalance = c.getBalance(address(this));
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        // attempt to add to balance, capturing revert
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint256 afterUserBalance = c.getBalance(address(this));
        uint256 afterContractBalance = address(c).balance;

        // If the call did not revert, user's recorded balance and contract balance must each increase by exactly amount
        assert(reverted || (afterUserBalance == beforeUserBalance + amount && afterContractBalance == beforeContractBalance + amount));
    }

    // allow receiving Ether so the test contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first deposit `amount` into c for this contract, then attempt withdraw.
    // Parameters: amount to deposit. The function is payable so the test harness can fund this contract.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Ensure we start with some recorded balance by calling addToBalance.
        // Capture balances before withdraw attempt.
        bool depositReverted;
        try c.addToBalance{value: amount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read before-values
        uint256 beforeUserBalance = c.getBalance(address(this));
        uint256 beforeContractBalance = address(c).balance;

        // Attempt withdraw and record whether it reverted
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // read after-values
        uint256 afterUserBalance = c.getBalance(address(this));
        uint256 afterContractBalance = address(c).balance;

        // If withdraw did not revert, then the recorded user balance must be zero and the contract's balance must not have increased.
        // We allow that deposit might have reverted; the rule is conditional on withdraw success only.
        assert(withdrawReverted || (afterUserBalance == 0 && afterContractBalance <= beforeContractBalance));
    }

    // allow receiving Ether so the test contract can fund calls and receive withdrawn Ether
    receive() external payable {}
}

